     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.time.LocalDate;
     4	
     5	import org.springframework.samples.petclinic.repository.OwnerRepository;
     6	import org.springframework.samples.petclinic.rest.escalation.DailyLimitException;
     7	
     8	/**
     9	 * Rejects a create request once 100 or more owners have already been registered
    10	 * today (by registrationDate), so the endpoint responds 429.
    11	 */
    12	public class RejectDailyLimit {
    13	
    14	    private static final int DAILY_LIMIT = 100;
    15	
    16	    public void service(OwnerRepository ownerRepository) throws DailyLimitException {
    17	        LocalDate today = LocalDate.now();
    18	        long count = ownerRepository.findAll().stream()
    19	                .filter(o -> today.equals(o.getRegistrationDate()))
    20	                .count();
    21	        if (count >= DAILY_LIMIT) {
    22	            throw new DailyLimitException();
    23	        }
    24	    }
    25	}
