     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.util.List;
     4	import java.util.regex.Pattern;
     5	
     6	import net.officefloor.plugin.variable.Val;
     7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
     9	
    10	/**
    11	 * When the create body carries an email, requires it to be a syntactically valid
    12	 * address and stores it lower-cased. An absent or blank email is left untouched; an
    13	 * invalid one is a 400 (reusing the missing-fields escalation). Runs before
    14	 * {@link BuildOwner}, so the persisted value is already lower-cased.
    15	 */
    16	public class NormalizeOwnerEmail {
    17	
    18	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
    19	
    20	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
    21	        String email = request.getEmail();
    22	        if (email == null || email.isBlank()) {
    23	            return;
    24	        }
    25	        if (!EMAIL.matcher(email).matches()) {
    26	            throw new MissingOwnerFieldsException(List.of("email"));
    27	        }
    28	        request.setEmail(email.toLowerCase());
    29	    }
    30	}
===== NormalizeOwnerTelephone.java =====
     1	package org.springframework.samples.petclinic.rest.function.owner;
     2	
     3	import java.util.List;
     4	
     5	import net.officefloor.plugin.variable.Val;
     6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
     7	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
     8	
     9	/**
    10	 * Rewrites the create body's telephone into E.164 form. Keeps a leading '+' and its
    11	 * country code when present; otherwise assumes '+61' and drops a single leading '0'
    12	 * from the national digits. Spaces, dashes and brackets are stripped and 8 to 15
    13	 * digits are required after the '+', so anything else is a 400. Runs before
    14	 * {@link BuildOwner} validates, so the stored value is the E.164 string.
    15	 */
    16	public class NormalizeOwnerTelephone {
    17	
    18	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
    19	        String raw = request.getTelephone().trim();
    20	        String digits = raw.replaceAll("\\D", "");
    21	        if (!raw.startsWith("+")) {
    22	            if (digits.startsWith("0")) {
    23	                digits = digits.substring(1);
    24	            }
    25	            digits = "61" + digits;
    26	        }
    27	        if (digits.length() < 8 || digits.length() > 15) {
    28	            throw new MissingOwnerFieldsException(List.of("telephone"));
    29	        }
    30	        request.setTelephone("+" + digits);
    31	    }
    32	}
