     7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerTelephoneException;
     8	
     9	/**
    10	 * Rejects a create body whose normalized telephone is already held by another owner,
    11	 * so the endpoint responds 409. Runs after {@link NormalizeOwnerTelephone} so the
    12	 * comparison uses the bare 10-digit value.
    13	 */
    14	public class RejectDuplicateOwnerTelephone {
    15	
    16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
    17	            throws DuplicateOwnerTelephoneException {
    18	        String telephone = request.getTelephone();
    19	        for (Owner existing : ownerRepository.findAll()) {
    20	            if (telephone.equals(existing.getTelephone())) {
    21	                throw new DuplicateOwnerTelephoneException(telephone);
    22	            }
    23	        }
    24	    }
    25	}

