     1	package org.springframework.samples.petclinic.mapper;
     2	
     3	/**
     4	 * Derives the owner's membership tier: {@code SILVER} when the owner had no namesakes
     5	 * at creation (namesakeCount is 0) and has an email on file, otherwise {@code BRONZE}.
     6	 * The value is a pure function of those two fields, so it needs no stored state.
     7	 */
     8	public final class MembershipTier {
     9	
    10	    private MembershipTier() {
    11	    }
    12	
    13	    public static String of(Integer namesakeCount, String email) {
    14	        boolean unique = namesakeCount != null && namesakeCount == 0;
    15	        boolean hasEmail = email != null && !email.isBlank();
    16	        return unique && hasEmail ? "SILVER" : "BRONZE";
    17	    }
    18	}
