     4	import org.springframework.samples.petclinic.model.Owner;
     5	import org.springframework.samples.petclinic.repository.OwnerRepository;
     6	
     7	/**
     8	 * Assigns the owner's {@code customerCode} formatted {@code <CITY3>-<LAST3>-<NNNN>}: the
     9	 * upper-cased first three letters of the city and of the last name, plus a per-city
    10	 * 4-digit sequence equal to one more than the owners already in that city.
    11	 */
    12	public class AssignCustomerCode {
    13	
    14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
